function FindDoctors(){
  const { doctors, catalogLoading, catalogError } = useCare()
  const location=useLocation()
  const params=new URLSearchParams(location.search)
  const [search,setSearch]=useState(params.get('q')||'')
  const [specialty,setSpecialty]=useState(params.get('specialty')||'All')
  const [gender,setGender]=useState('All')
  const [mode,setMode]=useState('All')
  const [sort,setSort]=useState('Recommended')
  const [maxFee,setMaxFee]=useState(6000)
  const [availableToday,setAvailableToday]=useState(false)
  const [highRating,setHighRating]=useState(false)
  const [videoOnly,setVideoOnly]=useState(false)
  const filtered=useMemo(()=>doctors
    .filter(d=>
      (!search||`${d.name} ${d.specialty} ${d.location}`.toLowerCase().includes(search.toLowerCase())) &&
      (specialty==='All'||d.specialty===specialty) &&
      (gender==='All'||d.gender===gender) &&
      (mode==='All'||d.mode.includes(mode)) &&
      Number(d.fee)<=maxFee &&
      (!availableToday||String(d.next||'').toLowerCase().startsWith('today')) &&
      (!highRating||Number(d.rating)>=4.8) &&
      (!videoOnly||d.mode.includes('Video'))
    )
    .sort((a,b)=>sort==='Fee: low to high'?a.fee-b.fee:sort==='Experience'?b.experience-a.experience:b.rating-a.rating),
    [doctors,search,specialty,gender,mode,sort,maxFee,availableToday,highRating,videoOnly])
  const clearFilters=()=>{setSearch('');setSpecialty('All');setGender('All');setMode('All');setSort('Recommended');setMaxFee(6000);setAvailableToday(false);setHighRating(false);setVideoOnly(false)}
  return <><PublicHeader/><main className="listingPage"><div className="container pageIntro"><span className="eyebrow">Verified clinicians</span><h1>Find care that fits your life.</h1><p>Search specialists, compare availability and book the format that works for you.</p></div><div className="container doctorSearchBar"><div><Search/><input aria-label="Search doctors directory" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Doctor, specialty or city"/></div><select aria-label="Specialty filter" value={specialty} onChange={e=>setSpecialty(e.target.value)}><option>All</option>{specialties.map(s=><option key={s[0]}>{s[0]}</option>)}</select><select aria-label="Gender filter" value={gender} onChange={e=>setGender(e.target.value)}><option>All</option><option>Female</option><option>Male</option></select><select aria-label="Consultation mode" value={mode} onChange={e=>setMode(e.target.value)}><option>All</option><option>Video</option><option>In-person</option></select></div><div className="container listingLayout"><aside className="filterPanel"><div className="filterTitle"><strong>Refine results</strong><button type="button" onClick={clearFilters}>Clear</button></div><label>Maximum fee <strong>{money(maxFee)}</strong><input type="range" min="2500" max="6000" step="100" value={maxFee} onChange={e=>setMaxFee(Number(e.target.value))}/></label><label className="check"><input type="checkbox" checked={availableToday} onChange={e=>setAvailableToday(e.target.checked)}/> Available today</label><label className="check"><input type="checkbox" checked={highRating} onChange={e=>setHighRating(e.target.checked)}/> 4.8+ rating</label><label className="check"><input type="checkbox" checked={videoOnly} onChange={e=>setVideoOnly(e.target.checked)}/> Video consultation</label><div className="infoBox"><ShieldCheck/><div><strong>Verified profiles</strong><p>Credentials and core profile information are reviewed before a clinician is listed.</p></div></div></aside><section className="results"><div className="resultsTop"><p><strong>{filtered.length}</strong> doctors match your search</p><select aria-label="Sort doctors" value={sort} onChange={e=>setSort(e.target.value)}><option>Recommended</option><option>Fee: low to high</option><option>Experience</option></select></div>{catalogError?<div role="alert" className="notice">{catalogError}</div>:catalogLoading?<p>Loading verified doctors…</p>:filtered.length?<div className="doctorGrid twoCols">{filtered.map(d=><DoctorCard key={d.id} doctor={d}/>)}</div>:<EmptyState icon={<Search/>} title="No doctors found" text="Try another specialty, city or consultation mode."/>}</section></div></main><PublicFooter/></>
}

function DoctorProfile(){const {id}=useParams(); const {doctors,catalogLoading,catalogError}=useCare(); const d=doctors.find(x=>x.id===id); const navigate=useNavigate(); if(!d)return <InfoPage eyebrow="Doctor directory" title={catalogLoading?'Loading doctor…':'Doctor unavailable'}><p>{catalogError||'Only verified clinicians can be booked.'}</p><Link to="/doctors">Back to doctors</Link></InfoPage>; return <><PublicHeader/><main className="profilePage"><div className="container breadcrumb"><Link to="/doctors"><ChevronLeft/>Back to doctors</Link></div><div className="container doctorProfileHero"><img src={d.image} alt=""/><div className="profileMain"><div className="profileTags"><span>{d.specialty}</span><span><BadgeCheck size={15}/> Verified</span></div><h1>{d.name}</h1><p>{d.clinic} · {d.location}</p><div className="profileMetrics"><div><strong>{d.rating}</strong><small>{d.reviews} patient reviews</small></div><div><strong>{d.experience} yrs</strong><small>Clinical experience</small></div><div><strong>{money(d.fee)}</strong><small>Consultation fee</small></div></div></div><div className="bookingSummary"><span className="statusPill"><span/> Next available</span><strong>{d.next}</strong><p>{d.mode.join(' · ')}</p><Button onClick={()=>navigate(`/patient/book?doctor=${d.id}`)}>Book appointment</Button></div></div><div className="container profileColumns"><section><h2>About {d.name.split(' ')[1]}</h2><p>{d.about}</p><h2>Areas of care</h2><div className="chipRow"><span>{d.specialty}</span><span>Preventive care</span><span>Follow-up care</span><span>Second opinions</span></div><h2>Patient feedback</h2><div className="reviewCard"><div><Stars rating={d.rating}/><strong>Clear, thoughtful and reassuring.</strong></div><p>“The consultation felt unhurried and the next steps were explained in a way I could actually follow.”</p><small>Verified patient · September 2026</small></div></section><aside><div className="sideCard"><h3>Clinic information</h3><div className="detailRow"><Building2/><div><strong>{d.clinic}</strong><span>{d.location}</span></div></div><div className="detailRow"><Video/><div><strong>Consultation options</strong><span>{d.mode.join(' and ')}</span></div></div><div className="detailRow"><MessageCircle/><div><strong>Languages</strong><span>{d.languages.join(', ')}</span></div></div></div><div className="sideCard"><h3>Credentials</h3><p>MBBS · FCPS · Board-certified specialist</p><p className="muted">Clinician profile information is provided by the care platform.</p></div></aside></div></main><PublicFooter/></>}

function InfoPage({title,eyebrow,children}){return <><PublicHeader/><main><div className="container simpleHero"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1></div><section className="container infoContent">{children}</section></main><PublicFooter/></>}
