function RoleShell({role,nav,children}){
  const {profile,session}=useCare()
  const liveName=profile?.role===role?profile.full_name:null
  const [mobile,setMobile]=useState(false)
  const location=useLocation()
  const title=nav.find(n=>n[0]===location.pathname)?.[2]||'Workspace'
  const searchTarget=role==='patient'?'/patient/doctors':role==='doctor'?'/doctor/patients':'/admin/users'
  const alertTarget=role==='patient'?'/patient/notifications':role==='doctor'?'/doctor/messages':'/admin/support'
  const profileTarget=role==='patient'?'/patient/profile':role==='doctor'?'/doctor/profile':'/admin/users'
  const initials=(liveName|| (role==='patient'?'Amina Khan':role==='doctor'?'Sarah Malik':'Medora Admin')).split(' ').filter(Boolean).slice(-2).map(x=>x[0]).join('').toUpperCase()
  return <div className="portal"><aside className={cls('sidebar',mobile&&'open')}><div className="sideTop"><Logo/><button aria-label="Close navigation" className="iconBtn closeSide" onClick={()=>setMobile(false)}><X/></button></div><div className="roleBadge"><span>{initials}</span><div><strong>{liveName || (role==='patient'?'Patient demo':role==='doctor'?'Doctor demo':'Admin demo')}</strong><small>{role[0].toUpperCase()+role.slice(1)} workspace</small></div></div><nav>{nav.map(([to,Icon,label])=><NavLink end={to===`/${role}`} to={to} key={to} onClick={()=>setMobile(false)}><Icon size={18}/>{label}</NavLink>)}</nav><div className="sideBottom"><Link to="/" onClick={()=>{localStorage.removeItem('medoraRole'); supabase?.auth.signOut()}}><LogOut size={18}/> Exit workspace</Link></div></aside><div className="portalMain"><header className="portalHeader"><button aria-label="Open navigation" className="iconBtn openSide" onClick={()=>setMobile(true)}><Menu/></button><div><small>{role[0].toUpperCase()+role.slice(1)} portal</small><h1>{title}</h1></div><div className="portalActions"><Link className="searchMini" to={searchTarget}><Search size={17}/> Search</Link><Link aria-label="Open alerts" className="iconBtn" to={alertTarget}><Bell size={19}/><span className="notificationDot"/></Link><Link aria-label="Open profile" className="profileMini" to={profileTarget}>{initials}</Link></div></header>{!session&&<div className="demoBanner"><ShieldCheck size={16}/><span><strong>Synthetic demo data</strong> — explore the full interface safely; sign in to use the live Supabase workflows.</span></div>}<main className="portalContent">{children}</main></div></div>
}

