function SectionTitle({title,action}){return <div className="panelTitle"><h2>{title}</h2>{action&&<button>{action}<ArrowRight/></button>}</div>}
function EmptyState({icon,title,text}){return <div className="emptyState"><span>{icon}</span><h3>{title}</h3><p>{text}</p></div>}

function PatientDashboard(){return <RoleShell role="patient" nav={patientNav}><div className="welcomeLine"><div><span className="eyebrow">Saturday, October 3</span><h2>Good afternoon, Amina.</h2><p>Here’s what needs your attention today.</p></div><Link className="btn btn-primary" to="/patient/book"><Plus/> Book appointment</Link></div><div className="metricsGrid"><Metric icon={CalendarCheck} label="Next appointment" value="Tomorrow · 5:30 PM" meta="Dr. Sarah Malik · Cardiology"/><Metric icon={Pill} label="Active prescriptions" value="3 medications" meta="1 refill due this week"/><Metric icon={TestTube2} label="New lab results" value="2 results" meta="Reviewed by your doctor"/><Metric icon={MessageCircle} label="Unread messages" value="2 messages" meta="From your care team"/></div><div className="dashboardGrid"><section className="panel span2"><SectionTitle title="Upcoming care" action="All appointments"/><div className="appointmentFeature"><div className="dateTile"><strong>04</strong><span>OCT</span></div><div className="appointmentInfo"><span className="statusPill green">Confirmed</span><h3>Cardiology follow-up</h3><p>Dr. Sarah Malik · Medora Heart Centre</p><div><span><Clock3/>5:30 PM</span><span><MapPin/>Lahore</span></div></div><div className="appointmentActions"><Button variant="secondary">Reschedule</Button><Button>View details</Button></div></div></section><section className="panel"><SectionTitle title="Care tasks"/><div className="taskList"><label><input type="checkbox"/> Upload previous ECG report</label><label><input type="checkbox"/> Confirm insurance details</label><label className="done"><input type="checkbox" defaultChecked/> Complete pre-visit form</label></div></section><section className="panel span2"><SectionTitle title="Recent health activity" action="View records"/><div className="timeline"><div><span><TestTube2/></span><div><strong>Lipid profile result available</strong><p>Reviewed by Dr. Sarah Malik</p></div><small>Today</small></div><div><span><Pill/></span><div><strong>Prescription renewed</strong><p>Atorvastatin 20 mg</p></div><small>Sep 28</small></div><div><span><MessageCircle/></span><div><strong>New care team message</strong><p>“Your results look stable…”</p></div><small>Sep 26</small></div></div></section><section className="panel"><SectionTitle title="Care team"/><div className="careTeam">{doctors.slice(0,3).map(d=><div key={d.id}><img src={d.image} alt=""/><div><strong>{d.name}</strong><small>{d.specialty}</small></div><button><MessageCircle/></button></div>)}</div></section></div></RoleShell>}

