 billing:<div className="billingGrid"><Metric icon={WalletCards} label="Outstanding balance" value="PKR 4,500" meta="1 invoice due"/><Metric icon={CreditCard} label="Saved payment method" value="•••• 4242" meta="Visa · expires 08/29"/><div className="panel span2"><SectionTitle title="Recent invoices"/><div className="listRows"><div><span>Cardiology consultation</span><strong>PKR 4,500</strong><small>Due Oct 4</small></div><div><span>Dermatology consultation</span><strong>PKR 3,200</strong><small>Paid Sep 18</small></div></div></div></div>,
